flashcards.question:
Que retourne cette fonction ?

```javascript
function mystery() {
  let x = 5;
  let y = 10;
  // Pas d'instruction return
}

console.log(mystery()); // ?
```

Quelle est la syntaxe pour une fonction fléchée ?

```javascript
// Version longue
const add1 = (a, b) => {
  return a + b;
};

// Version courte
const add2 = (a, b) => ???;
```

Qu'est-ce qu'une fonction d'ordre supérieur ?

```javascript
function processArray(arr, callback) {
  return arr.map(callback);
}

const double = x => x * 2;
processArray([1, 2, 3], double); // [2, 4, 6]
```

Qu'est-ce que le hissage de fonction ?

```javascript
// Ce code fonctionne-t-il ?
sayHello(); // ?

function sayHello() {
  console.log('Hello!');
}
```

Qu'est-ce qu'une fermeture (closure) ?

```javascript
function outerFunction(x) {
  return function innerFunction(y) {
    return x + y; // x est toujours accessible ici
  };
}

const addFive = outerFunction(5);
console.log(addFive(3)); // ?
```

Que fait la méthode `filter()` ?

```javascript
const numbers = [1, 2, 3, 4, 5, 6];
const evens = numbers.filter(x => x % 2 === 0);
console.log(evens); // ?
```

Que fait la méthode `reduce()` ?

```javascript
const numbers = [1, 2, 3, 4];
const sum = numbers.reduce((acc, curr) => acc + curr, 0);
console.log(sum); // ?
```

Qu'est-ce qu'une fonction pure ?

```javascript
// Fonction pure ?
function add(a, b) {
  return a + b;
}

// Fonction impure ?
let counter = 0;
function increment() {
  return ++counter;
}
```

Qu'est-ce qu'une IIFE ?

```javascript
(function() {
  console.log('Je m\'exécute immédiatement!');
})();

// Ou avec arrow function:
(() => {
  console.log('Moi aussi!');
})();
```

Comment définir des paramètres par défaut ?

```javascript
function greet(name = ???, age = ???) {
  console.log(`Hello ${name}, you are ${age}`);
}

greet(); // 'Hello Guest, you are 0'
```

Qu'est-ce que les paramètres rest ?

```javascript
function sum(first, ...others) {
  console.log('first:', first);  // ?
  console.log('others:', others); // ?
}

sum(1, 2, 3, 4, 5);
```

Quelle est la différence entre le hissage des déclarations de fonction et des expressions de fonction ?

```javascript
// Déclaration de fonction
console.log(func1()); // ?

function func1() {
  return 'Declaration';
}

// Expression de fonction
console.log(func2()); // ?

const func2 = function() {
  return 'Expression';
};
```

Qu'est-ce qu'une fonction callback ?

```javascript
function processData(data, callback) {
  const result = data.toUpperCase();
  callback(result);
}

processData('hello', function(result) {
  console.log(result); // ?
});
```

Quel est le contexte `this` dans les fonctions fléchées vs les fonctions régulières ?

```javascript
const obj = {
  name: 'Alice',
  regular: function() {
    console.log(this.name); // ?
  },
  arrow: () => {
    console.log(this.name); // ?
  }
};

obj.regular();
obj.arrow();
```

Qu'est-ce qu'une fonction usine (factory function) ?

```javascript
function createPerson(name, age) {
  return {
    name: name,
    age: age,
    greet: function() {
      return `Hello, I'm ${this.name}`;
    }
  };
}

const person1 = createPerson('Alice', 30);
console.log(person1.greet()); // ?
```

Comment déstructurer les paramètres dans une fonction ?

```javascript
// Pour les objets
function processUser({name, age, email}) {
  console.log(name, age, email);
}

// Pour les tableaux
function processCoords([x, y, z]) {
  console.log(x, y, z);
}

processUser({name: 'Alice', age: 30, email: 'alice@test.com'});
processCoords([1, 2, 3]);
```
